+import { CycleError, DuplicateTaskError, UnknownDependencyError } from "./errors.ts";
+import type { TaskSpec } from "./tasks.ts";
+
+/** Result of planning tasks. */
+export interface PlanResult {
+  /** Every task id, in execution order. */
+  order: string[];
+  /** stages[k]: tasks that can run at the earliest in round k. */
+  stages: string[][];
+}
+
+/**
+ * Plan tasks respecting dependencies and priorities.
+ *
+ * Order is built one task at a time picking the highest priority ready task.
+ * Stages are computed as 1 + max stage of dependencies.
+ *
+ * @throws DuplicateTaskError if any id appears more than once
+ * @throws UnknownDependencyError if a dependency is not in the task list
+ * @throws CycleError if the graph contains a cycle
+ */
+export function planOrder(tasks: TaskSpec[]): PlanResult {
+  const n = tasks.length;
+  if (n === 0) return { order: [], stages: [] };
+
+  // R3 step 1: duplicate ids
+  const count = new Map<string, number>();
+  const firstPos = new Map<string, number>();
+  for (let i = 0; i < n; i++) {
+    const id = tasks[i]!.id;
+    if (!count.has(id)) {
+      count.set(id, 1);
+      firstPos.set(id, i);
+    } else {
+      count.set(id, (count.get(id) ?? 0) + 1);
+    }
+  }
+  const duplicates: { id: string; pos: number }[] = [];
+  for (const [id, c] of count) {
+    if (c > 1) duplicates.push({ id, pos: firstPos.get(id)! });
+  }
+  if (duplicates.length > 0) {
+    duplicates.sort((a, b) => a.pos - b.pos);
+    throw new DuplicateTaskError(duplicates.map((d) => d.id));
+  }
+
+  // Map id -> index
+  const idToIndex = new Map<string, number>();
+  for (let i = 0; i < n; i++) idToIndex.set(tasks[i]!.id, i);
+
+  // R3 step 2: unknown dependency
+  for (let i = 0; i < n; i++) {
+    const t = tasks[i]!;
+    for (let j = 0; j < t.dependsOn.length; j++) {
+      const dep = t.dependsOn[j]!;
+      if (!idToIndex.has(dep)) {
+        throw new UnknownDependencyError(t.id, dep);
+      }
+    }
+  }
+
+  // Build graph structures with deduped depends
+  const uniqueDeps: number[][] = new Array(n);
+  const indegree = new Array<number>(n).fill(0);
+  const dependents: number[][] = new Array(n);
+  for (let i = 0; i < n; i++) dependents[i] = [];
+
+  for (let i = 0; i < n; i++) {
+    const deps = tasks[i]!.dependsOn;
+    const seen = new Set<string>();
+    const uniq: number[] = [];
+    for (const dep of deps) {
+      if (seen.has(dep)) continue;
+      seen.add(dep);
+      const depIdx = idToIndex.get(dep)!;
+      uniq.push(depIdx);
+    }
+    uniqueDeps[i] = uniq;
+    indegree[i] = uniq.length;
+    for (const d of uniq) {
+      dependents[d]!.push(i);
+    }
+  }
+
+  // Level for stages
+  const level = new Array<number>(n).fill(0);
+
+  // Heap for ready tasks: smallest = highest priority, earliest input
+  const heap: number[] = [];
+  function heapLess(a: number, b: number): boolean {
+    // return true if a should be above b
+    const pa = tasks[a]!.priority;
+    const pb = tasks[b]!.priority;
+    if (pa !== pb) return pa > pb;
+    return a < b;
+  }
+  function heapPush(idx: number): void {
+    heap.push(idx);
+    let i = heap.length - 1;
+    while (i > 0) {
+      const p = (i - 1) >> 1;
+      const pv = heap[p]!;
+      const iv = heap[i]!;
+      if (heapLess(pv, iv)) break;
+      const tmp = heap[p]!;
+      heap[p] = heap[i]!;
+      heap[i] = tmp;
+      i = p;
+    }
+  }
+  function heapPop(): number | undefined {
+    if (heap.length === 0) return undefined;
+    const top = heap[0]!;
+    const last = heap.pop()!;
+    if (heap.length > 0) {
+      heap[0] = last;
+      let i = 0;
+      while (true) {
+        const l = i * 2 + 1;
+        const r = l + 1;
+        let smallest = i;
+        if (l < heap.length) {
+          const sv = heap[smallest]!;
+          const lv = heap[l]!;
+          if (!heapLess(sv, lv)) smallest = l;
+        }
+        if (r < heap.length) {
+          const sv2 = heap[smallest]!;
+          const rv = heap[r]!;
+          if (!heapLess(sv2, rv)) smallest = r;
+        }
+        if (smallest === i) break;
+        const tmp = heap[i]!;
+        heap[i] = heap[smallest]!;
+        heap[smallest] = tmp;
+        i = smallest;
+      }
+    }
+    return top;
+  }
+
+  for (let i = 0; i < n; i++) {
+    if (indegree[i]! === 0) heapPush(i);
+  }
+
+  const orderIdx: number[] = [];
+
+  while (heap.length > 0) {
+    const cur = heapPop()!;
+    orderIdx.push(cur);
+    const depsOfDependents = dependents[cur]!;
+    for (const depIdx of depsOfDependents) {
+      const nextDeg = indegree[depIdx]! - 1;
+      indegree[depIdx] = nextDeg;
+      if (nextDeg === 0) {
+        // compute level as max of its dependencies +1
+        const deps = uniqueDeps[depIdx]!;
+        let maxL = -1;
+        for (const d of deps) {
+          const lv = level[d]!;
+          if (lv > maxL) maxL = lv;
+        }
+        level[depIdx] = maxL + 1;
+        heapPush(depIdx);
+      }
+    }
+  }
+
+  if (orderIdx.length !== n) {
+    // Cycle exists: find remaining nodes
+    const remaining = new Set<number>();
+    for (let i = 0; i < n; i++) if (indegree[i]! > 0) remaining.add(i);
+
+    // Build adjacency for remaining subgraph following dependency edges, filtered to remaining
+    // uniqueDeps already contains dependency indices
+    const state = new Array<number>(n).fill(0); // 0 unvisited,1 visiting,2 done
+    const parent = new Array<number>(n).fill(-1);
+
+    let foundCycle: string[] | null = null;
+
+    for (const start of remaining) {
+      if (state[start]! !== 0 || foundCycle) break;
+      // iterative DFS
+      const stack: { v: number; nextIdx: number; filtered: number[] }[] = [];
+      // prepare filtered deps for start
+      const filt0 = uniqueDeps[start]!.filter((d) => remaining.has(d));
+      stack.push({ v: start, nextIdx: 0, filtered: filt0 });
+      state[start] = 1;
+      parent[start] = -1;
+
+      while (stack.length > 0 && !foundCycle) {
+        const frame = stack[stack.length - 1]!;
+        const v = frame.v;
+        if (frame.nextIdx < frame.filtered.length) {
+          const w = frame.filtered[frame.nextIdx++]!;
+          if (state[w]! === 0) {
+            state[w] = 1;
+            parent[w] = v;
+            const filt = uniqueDeps[w]!.filter((d) => remaining.has(d));
+            stack.push({ v: w, nextIdx: 0, filtered: filt });
+          } else if (state[w]! === 1) {
+            // cycle v -> w
+            const nodes: number[] = [];
+            let cur: number = v;
+            nodes.push(cur);
+            while (cur !== w) {
+              cur = parent[cur]!;
+              // safety: if parent -1 break
+              if (cur === -1) break;
+              nodes.push(cur);
+            }
+            // nodes is v .. w ? Actually we pushed v then traversed parents up to w, so v -> parent[v] ... -> w
+            // But if parent chain goes v -> ... -> w, nodes currently [v, parent[v], ..., w]
+            // Reverse to get w .. v
+            nodes.reverse();
+            // Convert to ids, each depends on next, close loop
+            const cycleIds = nodes.map((idx) => tasks[idx]!.id);
+            cycleIds.push(cycleIds[0]!);
+            foundCycle = cycleIds;
+            break;
+          } else {
+            // visited done, ignore
+          }
+        } else {
+          state[v] = 2;
+          stack.pop();
+        }
+      }
+    }
+
+    if (!foundCycle) {
+      // fallback: self-loop or generic
+      // find any remaining node that depends on itself
+      for (const idx of remaining) {
+        if (uniqueDeps[idx]!.includes(idx)) {
+          foundCycle = [tasks[idx]!.id, tasks[idx]!.id];
+          break;
+        }
+      }
+    }
+    if (!foundCycle) {
+      // As last resort, construct trivial cycle from first remaining
+      const first = remaining.values().next().value as number;
+      foundCycle = [tasks[first]!.id, tasks[first]!.id];
+    }
+    throw new CycleError(foundCycle);
+  }
+
+  const order = orderIdx.map((i) => tasks[i]!.id);
+
+  // Build stages from levels
+  let maxLevel = 0;
+  for (let i = 0; i < n; i++) if (level[i]! > maxLevel) maxLevel = level[i]!;
+  const stages: string[][] = [];
+  for (let k = 0; k <= maxLevel; k++) stages.push([]);
+  // Collect indices per level
+  const perLevel: number[][] = [];
+  for (let k = 0; k <= maxLevel; k++) perLevel.push([]);
+  for (let i = 0; i < n; i++) perLevel[level[i]!]!.push(i);
+  for (let k = 0; k <= maxLevel; k++) {
+    const arr = perLevel[k]!;
+    arr.sort((a, b) => {
+      const pa = tasks[a]!.priority;
+      const pb = tasks[b]!.priority;
+      if (pa !== pb) return pb - pa;
+      return a - b;
+    });
+    stages[k] = arr.map((i) => tasks[i]!.id);
+  }
+
+  // Remove trailing empty? According spec no stage empty, but if n==0 handled.
+  return { order, stages };
+}
